from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'exercises'
OUT.mkdir(exist_ok=True)
MODEL=r'''/* 本版新编教学模型。SI单位；与真实实验数据分开。 */
(function(root){
'use strict';
function finite(...xs){if(xs.some(x=>!Number.isFinite(x)))throw Error('请完整填写有限数值。');}
function positive(...xs){finite(...xs);if(xs.some(x=>x<=0))throw Error('频率、周期数、质量、电阻等须大于零。');}
function paper(p){let {f,n,g,a0,a1,a2,b0,b1,b2}=p;positive(f,n,g);finite(a0,a1,a2,b0,b1,b2);if(!Number.isInteger(n))throw Error('周期数须为正整数。');if(!(a0<a1&&a1<a2&&b0<b1&&b1<b2&&b1>a1))throw Error('每组三点须递增，B须在A之后；两组允许共用点。');let T=n/f,vA=(a2-a0)/100/(2*T),vB=(b2-b0)/100/(2*T),dh=(b1-a1)/100,potential=g*dh,kinetic=(vB*vB-vA*vA)/2;return {T,vA,vB,dh,potential,kinetic,D:potential-kinetic};}
function spring({m,k,A,t}){positive(m,k);finite(A,t);if(A<0||t<0)throw Error('振幅和时间不可为负。');let w=Math.sqrt(k/m),T=2*Math.PI/w,x=A*Math.cos(w*t),v=-A*w*Math.sin(w*t),a=-w*w*x,K=m*v*v/2,U=k*x*x/2;return {w,T,x,v,a,K,U,E:K+U};}
function potential({a,b,p,U}){finite(a,b,p,U);if(!(a<p&&p<b))throw Error('观察点必须严格位于两板之间：a < p < b。');if(U<0)throw Error('本练习使用非负端电压。');return {V:U*(p-a)/(b-a),E:U/((b-a)/100),d:b-a};}
function rc({R,C,U,V0,dt,mode}){positive(R,C);finite(U,V0,dt);if(U<0||dt<0)throw Error('电源电压和时间间隔不可为负。');if(!['charge','discharge'].includes(mode))throw Error('未知开关状态。');let target=mode==='charge'?U:0,tau=R*C,V=target+(V0-target)*Math.exp(-dt/tau),i=(target-V)/R;return {V,i,tau,energy:C*V*V/2};}
const api={paper,spring,potential,rc};if(typeof module!=='undefined'&&module.exports)module.exports=api;root.Physics=api;
})(typeof window!=='undefined'?window:globalThis);
'''
(OUT/'models.js').write_text(MODEL,encoding='utf-8')
CSS='''*{box-sizing:border-box}html{color-scheme:light}body{margin:0;background:#f4f4ee;color:#24343b;font:17px/1.7 -apple-system,BlinkMacSystemFont,"PingFang SC","Microsoft YaHei",sans-serif}header,main,footer{max-width:1120px;margin:auto;padding:22px}header{padding-bottom:0}a{color:#075c5c}h1{font-size:clamp(25px,4vw,38px);line-height:1.35;margin:14px 0}h2{font-size:23px}.tag{font-size:13px;letter-spacing:.1em;color:#586b70}.intro{max-width:850px}main{display:grid;gap:18px}.card{background:#fff;border:1px solid #dbe3df;border-radius:14px;padding:22px;min-width:0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:14px}label{display:block;font-size:15px}input,textarea,select{width:100%;padding:10px;border:1px solid #9dada8;border-radius:6px;background:white;color:#172f37;font:inherit}textarea{min-height:130px}button{padding:10px 17px;margin:5px 6px 5px 0;border:1px solid #126164;border-radius:7px;background:#126164;color:white;font:inherit;cursor:pointer}button.secondary{background:#fff;color:#126164}button:focus-visible,input:focus-visible,textarea:focus-visible{outline:3px solid #c77d31;outline-offset:3px}.muted{color:#596b70;font-size:14px}.notice{border-left:4px solid #b77b35;background:#fff7e8;padding:12px 16px}.error{color:#a12e25}.metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(145px,1fr));gap:12px}.metric{background:#f1f6f4;border-radius:9px;padding:14px;overflow-wrap:anywhere}.metric b{display:block;font-size:24px;font-variant-numeric:tabular-nums}.metric small{display:block;font-size:13px}canvas{width:100%;height:auto;display:block;background:#fafcfb;border-radius:8px}table{width:100%;border-collapse:collapse}th,td{border-bottom:1px solid #ddd;padding:9px;text-align:left}.print-only{display:none}.eq{font-family:Georgia,"Songti SC",serif;font-size:20px}.bars{display:flex;gap:15px;align-items:end;height:170px}.bar-wrap{flex:1;text-align:center;height:100%;display:flex;flex-direction:column;justify-content:end}.bar{background:#277d79;min-height:1px}.bar.u{background:#ad7434}.bar.e{background:#435b74}footer{font-size:13px;color:#596b70;border-top:1px solid #d8e0dc;margin-top:20px}@media(max-width:600px){header,main,footer{padding:16px}.card{padding:16px}.grid{grid-template-columns:1fr 1fr}button{font-size:15px}.metric b{font-size:21px}}@media print{body{background:#fff;font-size:10pt}header,main,footer{max-width:none;padding:0}header a,.no-print,button,footer{display:none!important}.card{border:0;padding:10px 0;break-inside:avoid}.print-only{display:block;white-space:pre-wrap;overflow-wrap:anywhere}textarea{display:none}input{border:0;padding:0;font-size:10pt}h1{font-size:20pt}.notice{background:white}canvas{max-height:9cm;object-fit:contain}.metrics{grid-template-columns:repeat(3,1fr)}.metric{background:none;border:1px solid #aaa}.card.record{break-inside:auto}#result[hidden]{display:none!important}@page{size:A4;margin:16mm}}'''
COMMON=r'''const $=s=>document.querySelector(s);const $$=s=>Array.from(document.querySelectorAll(s));function num(id){const el=$(id);if(el.value.trim()==='')throw Error('请填写所有数值，不要用空白代替零。');const x=Number(el.value);if(!Number.isFinite(x))throw Error('请输入有限数值。');return x;}function fmt(x,n=4){return Math.abs(x)<1e-11?(0).toFixed(n):x.toFixed(n);}function metric(label,val,unit){return `<div class="metric"><small>${label}</small><b>${val}</b><small>${unit}</small></div>`;}function arrow(ctx,x,y,dx,color,label){ctx.strokeStyle=color;ctx.fillStyle=color;ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+dx,y);ctx.stroke();if(Math.abs(dx)>1){let sign=Math.sign(dx);ctx.beginPath();ctx.moveTo(x+dx,y);ctx.lineTo(x+dx-sign*9,y-5);ctx.lineTo(x+dx-sign*9,y+5);ctx.closePath();ctx.fill();}ctx.font='18px sans-serif';ctx.fillText(label,x,y-12);}'''
def field(id,label,value,step='any',extra=''):
    return f'<label>{label}<input id="{id}" type="number" value="{value}" step="{step}" {extra}></label>'
def save(name,title,desc,body,js):
    doc=f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}｜把物理想法做出来</title><style>{CSS}</style></head><body><header><a href="../index.html">← 返回书稿与练习目录</a><p class="tag">离线练习 · 本版新编 · 不上传数据</p><h1>{title}</h1><p class="intro">{desc}</p></header><main>{body}</main><footer>2026-09-11 · 教学示例，不是原装置复原或真实测量。HTML文件不自动保存本次操作记录。公式核查脚本见 editorial/test_models.js。</footer><script>{MODEL}\n{COMMON}\n{js}</script></body></html>'''
    (OUT/name).write_text(doc,encoding='utf-8')
body='''<section class="card"><h2>输入与条件</h2><p>位置从同一原点量起，向下为正。A、B为先后状态；每组三点对称取时，两组允许共用计数点。</p><div class="grid">'''
body+=field('f','打点频率 f / Hz','50')+field('n','相邻计数点间周期数 n','1','1')+field('g','g / (m/s²)','9.80')
body+='</div><h3>位置测量 / cm</h3><div class="grid">'
for id,label in [('a0','A前一个 sA−'),('a1','A点 sA'),('a2','A后一个 sA+'),('b0','B前一个 sB−'),('b1','B点 sB'),('b2','B后一个 sB+')]:body+=field(id,label,'')
body+='''</div><div class="no-print"><button id="calc">计算</button><button class="secondary" id="sample">填入示意检查数据</button><button class="secondary" id="clear">清空位置</button></div><p id="status" role="status">尚未计算。</p><p class="muted">T=n/f；v≈(s后−s前)/(2T)。n为周期数，不是首尾都计入的点数。示意数据仅用于核对程序，不是实验记录。</p></section><section id="result" class="card" hidden><h2>当前输入对应的结果</h2><div id="metrics" class="metrics"></div><p>差值 D = gΔh − (vB²−vA²)/2，保留正负号；本页不设“验证成功”阈值。</p></section><section class="card record"><h2>保留你的解释</h2><label>小组/记录名称<input id="group" type="text" placeholder="可不填写个人姓名"></label><label>结论、测量局限与需要继续检查的问题<textarea id="notes" placeholder="请自己说明，不由程序代写结论。"></textarea></label><div class="print-only" id="printedNotes"></div><button class="no-print secondary" id="print">打印 / 保存 PDF</button><p class="muted no-print">计算输入一变，旧结果立即撤下；名称和结论变化不影响计算。打印前检查长结论末尾是否完整。</p></section>'''
js=r'''let validResult=null;const ids=['f','n','g','a0','a1','a2','b0','b1','b2'];function invalidate(){validResult=null;$('#result').hidden=true;$('#status').className='';$('#status').textContent='输入已变化；旧结果已撤下，请重新计算。';}ids.forEach(id=>$('#'+id).addEventListener('input',invalidate));$('#calc').onclick=()=>{try{let p=Object.fromEntries(ids.map(id=>[id,num('#'+id)]));let r=Physics.paper(p);validResult=r;$('#metrics').innerHTML=metric('计数点间隔 T',fmt(r.T,5),'s')+metric('vA',fmt(r.vA),'m/s')+metric('vB',fmt(r.vB),'m/s')+metric('下降高度 Δh',fmt(r.dh,5),'m')+metric('gΔh',fmt(r.potential,5),'m²/s² = J/kg')+metric('(vB²−vA²)/2',fmt(r.kinetic,5),'m²/s² = J/kg')+metric('带符号差值 D',(r.D>=0?'+':'')+fmt(r.D,5),'m²/s² = J/kg');$('#result').hidden=false;$('#status').className='';$('#status').textContent='计算完成。请用独立计算核对；本页不判断实验是否成功。';}catch(e){validResult=null;$('#result').hidden=true;$('#status').className='error';$('#status').textContent=e.message;}};$('#sample').onclick=()=>{let s={f:50,n:1,g:9.8,a0:0,a1:1.82,a2:4,b0:1.82,b1:4,b2:6.54};for(let[id,v]of Object.entries(s))$('#'+id).value=v;invalidate();$('#status').textContent='已填入本版构造的检查数据；不是实测数据。请点击计算。';};$('#clear').onclick=()=>{ids.slice(3).forEach(id=>$('#'+id).value='');invalidate();};function syncPrint(){$('#printedNotes').textContent=$('#notes').value||'（尚未填写文字结论）';}$('#notes').addEventListener('input',syncPrint);window.addEventListener('beforeprint',syncPrint);$('#print').onclick=()=>{syncPrint();window.print();};window.exerciseState=()=>validResult;'''
save('01_paper_tape.html','纸带实验：让输入与结果对应','从测量位置估计两个状态的速度，再比较单位质量的能量变化。A不是默认的释放点。',body,js)
body='<section class="card"><div class="grid">'+field('m','质量 m / kg','1','0.1','min="0.1" max="20"')+field('k','劲度系数 k / (N/m)','4','0.1','min="0.1" max="100"')+field('A','振幅 A / m','0.2','0.01','min="0" max="0.5"')+'</div><p class="notice" id="status">水平、无阻力、理想轻弹簧。从右端静止释放。改变参数将暂停并重置初态。</p><button id="play">播放</button><button class="secondary" id="reset">复位</button><div class="no-print">'
for q,l in [(0,'0'),(.25,'T/4'),(.5,'T/2'),(.75,'3T/4'),(1,'T')]:body+=f'<button class="secondary phase" data-phase="{q}">{l}</button>'
body+='''</div><label>时刻 t / s<input id="time" type="number" min="0" value="0" step="0.01"></label></section><section class="card"><canvas id="scene" width="1000" height="310" aria-label="弹簧振子位置及速度、加速度箭头"></canvas><div id="metrics" class="metrics"></div></section><section class="card"><h2>能量显示</h2><p class="muted">柱形满高度固定为0.10 J，不自动缩放。超出时柱形截顶并给出提示，数值仍保留。</p><div class="bars"><div class="bar-wrap"><div id="barK" class="bar"></div><span>动能 K</span></div><div class="bar-wrap"><div id="barU" class="bar u"></div><span>势能 U</span></div><div class="bar-wrap"><div id="barE" class="bar e"></div><span>机械能 E</span></div></div><p id="scaleNote"></p><p class="eq">x=A cos(ωt)，v=−Aω sin(ωt)，ω=√(k/m)</p><p>这是按解析式计算的理想模型。能量恒定不是对真实弹簧的实验验证；箭头采用固定显示比例，精确值见数字。</p></section>'''
js=r'''let t=0,running=false,last=0;const ctx=$('#scene').getContext('2d');function params(){return {m:num('#m'),k:num('#k'),A:num('#A'),t};}function pause(){running=false;$('#play').textContent='播放';}function draw(){try{let p=params();if(p.A>0.5)throw Error('本页振幅显示范围为0至0.50 m。');let r=Physics.spring(p);$('#time').value=fmt(t,4);$('#metrics').innerHTML=metric('t',fmt(t,3),'s')+metric('周期 T',fmt(r.T,4),'s')+metric('位移 x',fmt(r.x),'m')+metric('速度 v',fmt(r.v),'m/s')+metric('加速度 a',fmt(r.a),'m/s²')+metric('K / U / E',`${fmt(r.K,3)} / ${fmt(r.U,3)} / ${fmt(r.E,3)}`,'J');for(let key of ['K','U','E'])$('#bar'+key).style.height=Math.min(r[key]/0.1,1)*130+'px';$('#scaleNote').textContent=r.E>0.10000001?'当前能量超过0.10 J显示上限；请读数值，不从截顶柱高比较。':'当前能量均在固定刻度范围内。';ctx.clearRect(0,0,1000,310);ctx.strokeStyle='#bdcbc6';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(90,205);ctx.lineTo(960,205);ctx.stroke();let cx=520+r.x*760;ctx.fillStyle='#6c7c80';ctx.fillRect(40,85,20,120);ctx.strokeStyle='#126164';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(60,142);for(let j=1;j<=24;j++){let xx=60+(cx-85)*j/24;ctx.lineTo(xx,142+(j===24?0:(j%2?15:-15)));}ctx.stroke();ctx.fillStyle='#126164';ctx.beginPath();ctx.arc(cx,142,26,0,2*Math.PI);ctx.fill();ctx.strokeStyle='#a4b4af';ctx.setLineDash([5,5]);ctx.beginPath();ctx.moveTo(520,45);ctx.lineTo(520,212);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#253a40';ctx.font='18px sans-serif';ctx.fillText('平衡位置 x=0',466,240);ctx.fillText('向右为正 →',810,240);arrow(ctx,cx,73,Math.max(-160,Math.min(160,r.v*240)),'#a86c2e','v');arrow(ctx,cx,280,Math.max(-160,Math.min(160,r.a*120)),'#405f82','a');$('#status').classList.remove('error');return r;}catch(e){pause();ctx.clearRect(0,0,1000,310);$('#metrics').textContent='';$('#status').classList.add('error');$('#status').textContent=e.message;return null;}}function reset(){pause();t=0;$('#status').textContent='参数/复位已重置初态：从右端静止释放。这是一次新运动。';draw();}['m','k','A'].forEach(id=>$('#'+id).addEventListener('input',reset));$('#reset').onclick=reset;$('#play').onclick=()=>{if(running){pause();return;}if(!draw())return;running=true;last=performance.now();$('#play').textContent='暂停';};$$('.phase').forEach(b=>b.onclick=()=>{pause();try{let r=Physics.spring({...params(),t:0});t=Number(b.dataset.phase)*r.T;draw();}catch(e){$('#status').classList.add('error');$('#status').textContent=e.message;}});$('#time').addEventListener('change',()=>{pause();try{t=num('#time');draw();}catch(e){$('#status').textContent=e.message;}});function frame(now){if(running){t+=(now-last)/1000;last=now;draw();}requestAnimationFrame(frame);}document.addEventListener('visibilitychange',()=>{if(document.hidden)pause();});window.exerciseState=()=>Physics.spring(params());draw();requestAnimationFrame(frame);'''
save('02_spring.html','弹簧振子：四个时刻核对同一状态','小球、方向箭头、数值和能量来自同一个模拟时间。先预测，再选取T/4等关键时刻。',body,js)
body='<section class="card"><div class="grid">'+field('a','下板位置 a / cm','0','0.5')+field('b','上板位置 b / cm','10','0.5')+field('p','观察点固定坐标 p / cm','4','0.5')+field('U','端电压 U / V','6','0.5')+'</div><p class="notice" id="status">下板电势0，上板电势U。比较按钮保持观察点p=4 cm不动。忽略边缘效应。</p><button class="secondary" data-case="initial">初始：a=0，b=10</button><button class="secondary" data-case="lower">只上移下板：a=2</button><button class="secondary" data-case="upper">只下移上板：b=8</button></section><section class="card"><canvas id="scene" width="1000" height="460" aria-label="固定观察点与电极位置、电势随坐标的线性分布"></canvas><div class="metrics" id="metrics"></div></section><section class="card"><h2>同样缩小间距，为什么一升一降？</h2><p class="eq">V(p)=U(p−a)/(b−a)，E的大小=U/(b−a)</p><p>下板上移时，观察点到零电势板的距离也缩短；上板下移时，这个距离不变。不能仅凭电场增强判断固定点电势升降。</p><p class="muted">长度输入为cm，计算E时换算为m。该图是理想平行板模型，不是有限水槽数值解，更不是实测读数。改变p相当于改选观察点，不属于上述固定点比较。</p></section>'
js=r'''const ctx=$('#scene').getContext('2d');function values(){return Object.fromEntries(['a','b','p','U'].map(id=>[id,num('#'+id)]));}function draw(){ctx.clearRect(0,0,1000,460);try{let q=values(),r=Physics.potential(q);$('#status').classList.remove('error');$('#status').textContent='观察点 p='+q.p+' cm；下板0 V，上板'+q.U+' V。图为模型计算，不是测量。';$('#metrics').innerHTML=metric('固定点电势 V(p)',fmt(r.V,3),'V，相对下板')+metric('电场强度大小',fmt(r.E,2),'V/m')+metric('板间距离',fmt(r.d,2),'cm');let low=Math.min(-1,q.a-1),high=Math.max(11,q.b+1),y=z=>380-(z-low)/(high-low)*320;ctx.fillStyle='#e9f1ec';ctx.fillRect(100,y(q.b),325,y(q.a)-y(q.b));ctx.lineWidth=9;ctx.strokeStyle='#49748a';ctx.beginPath();ctx.moveTo(85,y(q.a));ctx.lineTo(445,y(q.a));ctx.stroke();ctx.strokeStyle='#b67635';ctx.beginPath();ctx.moveTo(85,y(q.b));ctx.lineTo(445,y(q.b));ctx.stroke();ctx.fillStyle='#223940';ctx.font='18px sans-serif';ctx.fillText('下板：a='+q.a+' cm，0 V',100,y(q.a)+27);ctx.fillText('上板：b='+q.b+' cm，U='+q.U+' V',100,y(q.b)-17);ctx.fillStyle='#a4312c';ctx.beginPath();ctx.arc(267,y(q.p),9,0,2*Math.PI);ctx.fill();ctx.fillText('p='+q.p+' cm（不随板移动）',125,y(q.p)-17);ctx.strokeStyle='#879996';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(560,385);ctx.lineTo(950,385);ctx.moveTo(560,385);ctx.lineTo(560,45);ctx.stroke();let xx=z=>585+(z-low)/(high-low)*335, yy=v=>365-v/Math.max(q.U,1)*275;ctx.strokeStyle='#126164';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(xx(q.a),yy(0));ctx.lineTo(xx(q.b),yy(q.U));ctx.stroke();ctx.fillStyle='#a4312c';ctx.beginPath();ctx.arc(xx(q.p),yy(r.V),8,0,2*Math.PI);ctx.fill();ctx.fillStyle='#223940';ctx.fillText('V / V',560,32);ctx.fillText('坐标 / cm',848,429);ctx.fillText('a='+q.a,xx(q.a)-15,412);ctx.fillText('b='+q.b,xx(q.b)-15,412);ctx.fillText(fmt(r.V,3)+' V',Math.min(830,xx(q.p)+10),yy(r.V)-8);return r;}catch(e){$('#metrics').textContent='无有效结果。';$('#status').classList.add('error');$('#status').textContent=e.message;return null;}}['a','b','p','U'].forEach(id=>$('#'+id).addEventListener('input',draw));$$('[data-case]').forEach(el=>el.onclick=()=>{let c=el.dataset.case,vals={a:c==='lower'?2:0,b:c==='upper'?8:10,p:4,U:6};for(let[id,v]of Object.entries(vals))$('#'+id).value=v;draw();});window.exerciseState=()=>Physics.potential(values());draw();'''
save('03_potential.html','平行板电势：固定点，一升一降','同样把板间距从10 cm减为8 cm，观察点电势可以降到1.5 V，也可以升到3.0 V。',body,js)
body='<section class="card"><div class="grid">'+field('R','电阻 R / kΩ','10','1')+field('C','电容 C / μF','100','10')+field('U','电源 U / V','5','0.5')+'</div><p class="notice" id="status">初始未充电。切换充/放电保留电容电压；改变参数才重置。</p><button id="play">播放</button><button class="secondary" id="step">前进 τ/4</button><button class="secondary" id="switch">切换到放电</button><button class="secondary" id="reset">复位</button></section><section class="card"><div class="metrics" id="metrics"></div><canvas id="scene" width="1000" height="370" aria-label="电容电压随时间的连续记录"></canvas></section><section class="card"><h2>此刻电流沿哪个回路？</h2><p id="topology"></p><p class="eq">充电：VC=U+(V0−U)e^(−Δt/RC)<br>放电：VC=V0 e^(−Δt/RC)</p><p>正电流定义为流入电容正极板。切换瞬间电容电压连续，电流可以发生有限跳变。电路采用理想电源、理想开关及恒定R、C，不包含真实接触和传感器影响。</p><p class="muted">曲线只显示最近10个时间常数内、最多2000个状态点。当前计算状态不因显示窗口改变而重置；这不是硬件采集记录。</p></section>'
js=r'''let t=0,V=0,mode='charge',running=false,last=0,history=[[0,0]];const ctx=$('#scene').getContext('2d');function params(){return {R:num('#R')*1000,C:num('#C')*1e-6,U:num('#U')};}function pause(){running=false;$('#play').textContent='播放';}function state(){return Physics.rc({...params(),V0:V,dt:0,mode});}function draw(){try{let p=params(),r=state();$('#metrics').innerHTML=metric('总时间',fmt(t,3),'s')+metric('电容电压 VC',fmt(V,4),'V')+metric('电流 i',fmt(r.i*1000,4),'mA，流入正极板为正')+metric('时间常数 τ',fmt(r.tau,3),'s')+metric('电容储能',fmt(r.energy*1000,4),'mJ')+metric('开关状态',mode==='charge'?'充电':'放电','切换保持VC');$('#switch').textContent=mode==='charge'?'切换到放电':'切换到充电';$('#topology').textContent=mode==='charge'?'电源正极 → 电阻 → 电容正极；电容下端接公共参考点。':'电源正极与当前回路断开；电容通过电阻向公共参考点放电。';ctx.clearRect(0,0,1000,370);let xmax=Math.max(5*r.tau,t),xmin=Math.max(0,xmax-10*r.tau),xx=z=>80+(z-xmin)/(xmax-xmin)*850,yy=z=>300-z/Math.max(p.U,0.1)*240;ctx.strokeStyle='#869b96';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(80,30);ctx.lineTo(80,300);ctx.lineTo(945,300);ctx.stroke();ctx.fillStyle='#243a40';ctx.font='18px sans-serif';ctx.fillText('VC / V',25,22);ctx.fillText('t / s',934,343);ctx.fillText(fmt(p.U,2),24,64);ctx.fillText(fmt(xmin,1),74,328);ctx.fillText(fmt(xmax,1),899,328);ctx.strokeStyle='#126164';ctx.lineWidth=3;ctx.beginPath();let first=true;for(let[tt,vv]of history){if(tt<xmin)continue;if(first){ctx.moveTo(xx(tt),yy(vv));first=false;}else ctx.lineTo(xx(tt),yy(vv));}ctx.stroke();ctx.fillStyle='#a86c2e';ctx.beginPath();ctx.arc(xx(t),yy(V),6,0,2*Math.PI);ctx.fill();$('#status').classList.remove('error');return r;}catch(e){pause();ctx.clearRect(0,0,1000,370);$('#metrics').textContent='';$('#status').classList.add('error');$('#status').textContent=e.message;return null;}}function advance(dt){let r=Physics.rc({...params(),V0:V,dt,mode});V=r.V;t+=dt;history.push([t,V]);if(history.length>2000)history.shift();draw();}function reset(){pause();t=0;V=0;mode='charge';history=[[0,0]];$('#status').textContent='已复位：初始未充电，参数改变代表一次新实验。';draw();}$('#reset').onclick=reset;['R','C','U'].forEach(id=>$('#'+id).addEventListener('input',reset));$('#switch').onclick=()=>{let previous=V;mode=mode==='charge'?'discharge':'charge';$('#status').textContent='开关已切换；电容电压仍为 '+fmt(previous,4)+' V。电流可发生跳变。';history.push([t,V]);draw();};$('#step').onclick=()=>{pause();try{advance(state().tau/4);}catch(e){$('#status').textContent=e.message;}};$('#play').onclick=()=>{if(running){pause();return;}if(!draw())return;last=performance.now();running=true;$('#play').textContent='暂停';};function frame(now){if(running){let dt=(now-last)/1000;last=now;try{advance(dt);}catch(e){pause();$('#status').textContent=e.message;}}requestAnimationFrame(frame);}document.addEventListener('visibilitychange',()=>{if(document.hidden)pause();});window.exerciseState=()=>({t,V,mode,...state()});draw();requestAnimationFrame(frame);'''
save('04_rc.html','RC充放电：让切换属于同一次过程','未充满就切到放电，电容电压不能跳回零或电源电压。按τ/4推进，可以复现书中的数值例子。',body,js)
